  [inst_2 : L.Encodable] [inst_3 : L.LORDefinable] (φ : FFL.FirstOrder.Arithmetic.Bootstrapping.Semiformula V L 1),
  FFL.FirstOrder.Arithmetic.Bootstrapping.IsSemiformula L 1 φ.val = True

∀ {F : Type} {α β : outParam Type} {inst : FFL.LogicalConnective α} {inst_1 : FFL.LogicalNeutral α}
  {inst_2 : FFL.LogicalConnective β} {inst_3 : FFL.LogicalNeutral β} {inst_4 : FunLike F α β}
  [self : FFL.LogicalConnective.HomClass F α β] (f : F) (φ : α), f (∼φ) = ∼f φ

∀ {V : Type} [inst : FFL.ORingStructure V] [inst_1 : V↓[ℒₒᵣ] ⊧* 𝗜𝚺₁] {L : FFL.FirstOrder.Language}
  [inst_2 : L.Encodable] [inst_3 : L.LORDefinable] {n m : ℕ} (σ : FFL.FirstOrder.Semisentence L n),
  ⌜⌜σ⌝⌝ = FFL.FirstOrder.Arithmetic.Bootstrapping.Arithmetic.typedNumeral ⌜σ⌝

∀ {V : Type} [inst : FFL.ORingStructure V] [inst_1 : V↓[ℒₒᵣ] ⊧* 𝗜𝚺₁] {L : FFL.FirstOrder.Language}
  [inst_2 : L.Encodable] [inst_3 : L.LORDefinable] {k n : ℕ}
  (v : FFL.FirstOrder.Arithmetic.Bootstrapping.SemitermVec V L (k + 1) n),
  v.val = adjoin (Matrix.vecHead v).val (FFL.FirstOrder.Arithmetic.Bootstrapping.SemitermVec.val (Matrix.vecTail v))
